import type { ComponentDefinition, ComponentSet } from '../domain/types';
import { deepFreezeComponentSets, PROVIDER_META } from './builtin';

/** Full official icon libraries (#92), generated by scripts/import-official-icons.mjs. */
export type OfficialProvider = keyof typeof PROVIDER_META;
export const OFFICIAL_PROVIDERS: readonly OfficialProvider[] = ['aws', 'azure', 'gcp', 'kubernetes'];

export interface RawOfficialComponent { type: string; name: string; aliases?: string[]; iconSvg: string }
export interface RawOfficialSet { id: string; name: string; version: string; category: string; components: RawOfficialComponent[] }
export interface RawOfficialLibrary { provider: OfficialProvider; package: string; retrieved: string; sets: RawOfficialSet[] }

/** Aliases are ID-like in the catalog contract: ASCII letters, digits, ".", "_", ":" and "-". */
function aliasId(alias: string): string {
  return alias.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Za-z0-9._:-]+/g, '-').replace(/^-+|-+$/g, '');
}

/** One component set per provider category, so a document only embeds the categories it uses. */
function aliasesOf(aliases: string[] | undefined): Pick<ComponentDefinition, 'aliases'> {
  const ids = [...new Set((aliases ?? []).map(aliasId).filter(Boolean))];
  return ids.length ? { aliases: ids } : {};
}

export function toOfficialComponentSets(library: RawOfficialLibrary): ComponentSet[] {
  const theme = PROVIDER_META[library.provider];
  return deepFreezeComponentSets(library.sets.map((set) => ({
    id: set.id,
    name: set.name,
    version: set.version,
    components: set.components.map((component): ComponentDefinition => ({
      type: component.type,
      name: component.name,
      provider: library.provider,
      category: set.category,
      ...aliasesOf(component.aliases),
      defaultWidth: 160,
      defaultHeight: 80,
      style: { stroke: theme.stroke, fill: theme.fill },
      metadata: { provenance: 'official-architecture-icon', source: theme.source, terms: theme.terms, package: library.package },
      iconSvg: component.iconSvg,
    })),
  })));
}
